const {test}=require('node:test');const assert=require('node:assert/strict');
test('tap, sideways move and short upward pull cannot remove a tile',async()=>{const {pullSample}=await import('../sandbox-model.mjs');assert.equal(pullSample(0,0,1000).ready,false);assert.equal(pullSample(150,130,1000).ready,false);assert.equal(pullSample(1,70,1000).ready,false);assert.equal(pullSample(0,120,80).ready,false);assert.equal(pullSample(0,120,300).ready,true);});
test('pull resistance remains bounded at extreme pointer distances',async()=>{const {pullSample}=await import('../sandbox-model.mjs');for(const y of [0,10,80,110,10000]){const p=pullSample(0,y,1000);assert.ok(p.lift>=0&&p.lift<=4);assert.ok(Math.abs(p.wiggle)<.04);}});
test('dashboard uses real town counts and closes resolved cases',async()=>{const {dashboardData}=await import('../sandbox-model.mjs');const d=dashboardData({}, {},{households:[{adults:2,children:1,food:4}],services:{care:{local:0,outside:1,demand:1}},market:{grain:7},cases:[{status:'closed'},{status:'open'}]});assert.equal(d.metrics.find(x=>x.label==='People').value,3);assert.equal(d.metrics.find(x=>x.label==='Cases').value,1);assert.equal(d.metrics.find(x=>x.label==='Care').ratio,1);assert.equal(d.bars[0][1],7);});
test('composition-only tiles never present invented live metrics',async()=>{const {dashboardData}=await import('../sandbox-model.mjs');const d=dashboardData({recipe:{types:['a','b']},capabilities:{}},{rotation:2});assert.equal(d.live,false);assert.equal(d.metrics[0].value,2);assert.equal(d.metrics[1].value,'120°');});
test('glass inertia settles without modifying base data and respects reduced motion',async()=>{const {body,advance}=await import('../sandbox-inertia.mjs');const b=body();advance(b,.016,{dx:1});assert.ok(b.x<0);for(let i=0;i<900;i++)advance(b,.016);assert.ok(Math.abs(b.x)<.001);advance(b,.016,{dx:1,reduced:true});assert.equal(b.x,0);});
